import{Z as t,e as n,f as i,a0 as o}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Brevo (Sendinblue)","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/brevo-sendinblue.md","filePath":"integrations/email-marketing/brevo-sendinblue.md","lastUpdated":null}'),a={name:"integrations/email-marketing/brevo-sendinblue.md"};function s(r,e,l,c,h,d){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="brevo-sendinblue" tabindex="-1">Brevo (Sendinblue) <a class="header-anchor" href="#brevo-sendinblue" aria-label="Permalink to &quot;Brevo (Sendinblue)&quot;">​</a></h1><p>Connect Brevo (Sendinblue) to send newsletter sign-ups to your chosen mailing list. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Brevo as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-brevo-api" tabindex="-1">Step 2. Connect to the Brevo API <a class="header-anchor" href="#step-2-connect-to-the-brevo-api" aria-label="Permalink to &quot;Step 2. Connect to the Brevo API&quot;">​</a></h3><ol><li>Go to <a href="https://www.brevo.com/" target="_blank">Brevo</a> and login to your account.</li><li>In the top-right corner, click on your profile and select <strong>SMTP &amp; API</strong>.</li><li>Click the <strong>+ Create a new API Key</strong> button, and give it a name.</li><li>Copy the <strong>API Key</strong> from Brevo and paste in the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Select the destination list and map its required email field to your form’s Email Address field. Map any additional fields your list requires using the variable picker. If you collect a newsletter opt-in, configure integration conditions so only visitors who choose it are sent.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h3 id="dynamic-list-assignment" tabindex="-1">Dynamic List Assignment <a class="header-anchor" href="#dynamic-list-assignment" aria-label="Permalink to &quot;Dynamic List Assignment&quot;">​</a></h3><p>By default, contacts are added to the list selected in the integration’s <strong>List</strong> setting. You can override this per submission by mapping a form field to the Brevo <strong>List</strong> integration field. This is useful when a dropdown on the form should determine which Brevo list the contact is subscribed to.</p><p>The static <strong>List</strong> setting is still required and acts as the fallback when no list is mapped. You can map a single list ID, comma-separated list IDs, or multiple values from a checkbox field.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Look up the test email in the selected list and check its mapped values and subscription state. If the provider requires confirmation, complete that step before expecting an active subscription.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',16)])])}const u=t(a,[["render",s]]);export{p as __pageData,u as default};
